from ledger import record, recorded


def _valid_amount(amount):
    return isinstance(amount, int) and not isinstance(amount, bool) and amount >= 0


def settle_payment(state, key, amount):
    """Server side: credit amount exactly once under key and return the balance."""
    if not isinstance(key, str) or not key:
        raise ValueError("invalid payment key")
    if not _valid_amount(amount):
        raise ValueError("invalid payment amount")
    previous = recorded(state, key)
    if previous is not None:
        if previous != amount:
            raise ValueError("payment key reused with a different amount")
        return state["total"]
    return record(state, key, amount)

from ledger import ReplyLost


def make_payment(send, invoice, amount, attempts=3):
    """Pay invoice through send(key, amount), retrying lost responses.

    The key is the invoice itself, so every send for one invoice, in this call,
    a later call or after a restart, carries the same idempotency key.
    """
    key = invoice
    for attempt in range(1, attempts + 1):
        try:
            return send(key, amount)
        except ReplyLost:
            if attempt >= attempts:
                raise
    raise ReplyLost("no attempt was made")
